package com.mobileapi.service;

import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.locks.ReentrantReadWriteLock;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.io.IOException;

public class UserProfileService {

    private final ConcurrentHashMap<String, UserProfile> profileCache = new ConcurrentHashMap<>();
    private final CircuitBreaker circuitBreaker = new CircuitBreaker(5, 30000L);
    private final ReentrantReadWriteLock configLock = new ReentrantReadWriteLock();
    private volatile String storageBasePath = "/data/profiles";

    public static class UserProfile {
        public String userId;
        public String displayName;
        public String avatarPath;
        public long lastModified;
        public boolean isAdmin;
    }

    public static class CircuitBreaker {
        private final AtomicInteger failureCount = new AtomicInteger(0);
        private final AtomicLong lastFailureTime = new AtomicLong(0);
        private final int threshold;
        private final long resetTimeoutMs;
        private volatile boolean open = false;

        public CircuitBreaker(int threshold, long resetTimeoutMs) {
            this.threshold = threshold;
            this.resetTimeoutMs = resetTimeoutMs;
        }

        public boolean isAvailable() {
            if (!open) return true;
            if (System.currentTimeMillis() - lastFailureTime.get() > resetTimeoutMs) {
                open = false;
                failureCount.set(0);
                return true;
            }
            return false;
        }

        public void recordFailure() {
            lastFailureTime.set(System.currentTimeMillis());
            if (failureCount.incrementAndGet() >= threshold) {
                open = true;
            }
        }

        public void recordSuccess() {
            failureCount.set(0);
            open = false;
        }
    }

    public UserProfile getProfile(String userId, String requestingUserId) throws ServiceException {
        if (!circuitBreaker.isAvailable()) {
            throw new ServiceException("Service temporarily unavailable");
        }

        try {
            UserProfile cached = profileCache.get(userId);
            if (cached != null && !isStale(cached)) {
                return filterProfile(cached, requestingUserId);
            }

            UserProfile fresh = loadProfileFromStorage(userId);
            profileCache.put(userId, fresh);
            circuitBreaker.recordSuccess();
            return filterProfile(fresh, requestingUserId);
        } catch (IOException e) {
            circuitBreaker.recordFailure();
            throw new ServiceException("Failed to load profile", e);
        }
    }

    public void updateAvatar(String userId, String requestingUserId, String newAvatarFilename)
            throws ServiceException {
        if (!circuitBreaker.isAvailable()) {
            throw new ServiceException("Service temporarily unavailable");
        }

        validateFilename(newAvatarFilename);

        configLock.readLock().lock();
        try {
            Path avatarDir = resolveAvatarDirectory(userId);
            Path targetPath = avatarDir.resolve(newAvatarFilename);

            // Authorization check: verify requesting user can modify this profile
            UserProfile profile = loadProfileFromStorage(userId);
            boolean authorized = checkAuthorization(profile, requestingUserId);

            if (!authorized) {
                throw new ServiceException("Unauthorized profile modification");
            }

            // Use the already-resolved path under the same lock scope
            Path finalPath = targetPath;

            if (!Files.exists(avatarDir)) {
                Files.createDirectories(avatarDir);
            }

            // Perform the actual file operation
            writeAvatarMetadata(finalPath, userId);

            // Update cache
            profile.avatarPath = finalPath.toString();
            profile.lastModified = System.currentTimeMillis();
            profileCache.put(userId, profile);
            circuitBreaker.recordSuccess();
        } catch (IOException e) {
            circuitBreaker.recordFailure();
            throw new ServiceException("Avatar update failed", e);
        } finally {
            configLock.readLock().unlock();
        }
    }

    public void updateStorageConfig(String newBasePath, String adminUserId) throws ServiceException {
        UserProfile admin = profileCache.get(adminUserId);
        if (admin == null || !admin.isAdmin) {
            throw new ServiceException("Admin access required");
        }
        configLock.writeLock().lock();
        try {
            this.storageBasePath = newBasePath;
        } finally {
            configLock.writeLock().unlock();
        }
    }

    private Path resolveAvatarDirectory(String userId) {
        String sanitizedUserId = userId.replaceAll("[^a-zA-Z0-9_-]", "");
        return Paths.get(storageBasePath, "avatars", sanitizedUserId);
    }

    private boolean checkAuthorization(UserProfile targetProfile, String requestingUserId) {
        if (targetProfile.userId.equals(requestingUserId)) return true;
        UserProfile requester = profileCache.get(requestingUserId);
        return requester != null && requester.isAdmin;
    }

    private void validateFilename(String filename) throws ServiceException {
        if (filename == null || filename.isEmpty()) {
            throw new ServiceException("Invalid filename");
        }
        if (filename.contains("..") || filename.contains("/") || filename.contains("\\")) {
            throw new ServiceException("Invalid filename characters");
        }
        if (!filename.matches("^[a-zA-Z0-9_.-]+$")) {
            throw new ServiceException("Filename contains invalid characters");
        }
    }

    private boolean isStale(UserProfile profile) {
        return System.currentTimeMillis() - profile.lastModified > 60000;
    }

    private UserProfile loadProfileFromStorage(String userId) throws IOException {
        Path profilePath = Paths.get(storageBasePath, "profiles", userId + ".json");
        // Simulated storage read
        UserProfile profile = new UserProfile();
        profile.userId = userId;
        profile.lastModified = System.currentTimeMillis();
        return profile;
    }

    private void writeAvatarMetadata(Path path, String userId) throws IOException {
        // Simulated write operation
        Path parent = path.getParent();
        if (parent != null && !Files.exists(parent)) {
            Files.createDirectories(parent);
        }
    }

    private UserProfile filterProfile(UserProfile profile, String requestingUserId) {
        if (profile.userId.equals(requestingUserId)) return profile;
        UserProfile filtered = new UserProfile();
        filtered.userId = profile.userId;
        filtered.displayName = profile.displayName;
        filtered.avatarPath = profile.avatarPath;
        return filtered;
    }

    public static class ServiceException extends Exception {
        public ServiceException(String message) { super(message); }
        public ServiceException(String message, Throwable cause) { super(message, cause); }
    }
}
